+        branch:   "main".to_string(),
+        tag:      None,
+        sha:      None,
+        provider: ScmProvider::Github,
+    })
+    .validate_with_scm(Some("http://localhost:3001"))
+    .expect("github target should validate");
+    assert_eq!(
