+        branch:   "main".to_string(),
+        tag:      None,
+        sha:      None,
+        provider: ScmProvider::Forgejo,
+    })
+    .validate_with_scm(None)
+    .expect_err("forgejo target without an instance URL should fail");
+    assert_eq!(
+        error,
